export function icon(name, cls = '') { return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] ?? paths.dumbbell}</svg>`; }
export function btn(action, label, symbol = '', cls = 'button', attrs = '') { return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${symbol ? icon(symbol) : ''}${esc(label)}</button>`; }
export function ib(action, label, symbol, attrs = '') { return `<button type="button" class="icon-button" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${icon(symbol)}</button>`; }
export function clock(ms, hours = false) { const s = Math.max(0, Math.floor(ms / 1000)); return hours || s >= 3600 ? `${Math.floor(s / 3600)}:${String(Math.floor(s % 3600 / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}` : `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; }
export const count = (n) => new Intl.NumberFormat('en', { maximumFractionDigits: 1 }).format(n);
export const date = (n) => new Date(n).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
export const longDate = (n) => new Date(n).toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
export const empty = (title, text, action = '') => `<div class="empty-state"><div class="empty-icon">${icon('dumbbell')}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
export const pill = (text, cls = '') => `<span class="pill ${cls}">${esc(text)}</span>`;
export const field = (label, input, help = '') => `<label class="field"><span>${esc(label)}</span>${input}${help ? `<small>${esc(help)}</small>` : ''}</label>`;
export const textInput = (name, value, max, placeholder = '') => `<input name="${name}" value="${esc(value)}" maxlength="${max}" placeholder="${esc(placeholder)}" autocomplete="off">`;
export const numberInput = (name, value, min = 0, max = 999, extra = '') => `<input name="${name}" type="number" inputmode="numeric" value="${esc(value)}" min="${min}" max="${max}" step="1" required ${extra}>`;
export function row(action, title, description, symbol, attrs = '', end = '') { return `<button type="button" class="list-row" data-action="${action}" ${attrs}><span class="row-icon">${icon(symbol)}</span><span class="row-copy"><strong>${esc(title)}</strong>${description ? `<small>${esc(description)}</small>` : ''}</span>${end || icon('chevron', 'row-chevron')}</button>`; }
export function top(title, subtitle = '', right = '') { return `<header class="page-header"><div>${subtitle ? `<div class="eyebrow">${esc(subtitle)}</div>` : ''}<h1>${esc(title)}</h1></div>${right}</header>`; }
export function backHeader(title, back = 'workouts', right = '') { return `<header class="compact-header">${ib('navigate', 'Back', 'back', `data-to="${esc(back)}"`)}<strong>${esc(title)}</strong>${right || '<span class="header-spacer"></span>'}</header>`; }
